"""括号匹配与最长连续有效括号子串。"""

_PAIRS = {')': '(', ']': '[', '}': '{'}
_OPENERS = '([{'


def is_balanced(s: str) -> bool:
    """判断 s 中的括号 ()[]{} 是否配对且嵌套正确。

    非括号字符一律忽略；空串视为平衡。
    """
    stack: list[str] = []
    for ch in s:
        if ch in _OPENERS:
            stack.append(ch)
        elif ch in _PAIRS:
            if not stack or stack.pop() != _PAIRS[ch]:
                return False
    return not stack


def longest_valid(s: str) -> int:
    """返回 s（仅由 '(' 与 ')' 组成）中连续有效括号子串的最大长度。"""
    stack: list[int] = [-1]
    best = 0
    for i, ch in enumerate(s):
        if ch == '(':
            stack.append(i)
        else:
            stack.pop()
            if not stack:
                stack.append(i)
            else:
                best = max(best, i - stack[-1])
    return best
